import React from "react";

const severityColors = {
  High: "#ff4d4f",
  Medium: "#faad14",
  Low: "#52c41a",
};

export default function AlertsTable({ alerts = [], blockedIPs = [], onBlockIP = () => {}, onUnblockIP = () => {} }) {
  const safeAlerts = Array.isArray(alerts) ? alerts : [];
  return (
    <table
      style={{
        width: "100%",
        borderCollapse: "collapse",
        fontSize: "0.9rem",
      }}
    >
      <thead>
        <tr style={{ background: "#f0f2f5" }}>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Time</th>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Source IP</th>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Dest IP</th>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Type</th>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Severity</th>
          <th style={{ padding: "0.6rem", textAlign: "left" }}>Detail</th>
          <th style={{ padding: "0.6rem", textAlign: "center" }}>Mitigation</th>
        </tr>
      </thead>
      <tbody>
        {safeAlerts.length === 0 ? (
          <tr>
            <td colSpan="7" style={{ textAlign: "center", padding: "1.5rem", color: "#888" }}>
              Waiting for live alerts...
            </td>
          </tr>
        ) : (
          safeAlerts.map((a) => {
            const isBlocked = blockedIPs.includes(a.source_ip);
            return (
              <tr key={a.id || Math.random()} style={{ borderBottom: "1px solid #e8e8e8" }}>
                <td style={{ padding: "0.6rem" }}>{a.detected_at ? new Date(a.detected_at).toLocaleTimeString() : "-"}</td>
                <td style={{ padding: "0.6rem" }}>
                  <span style={{ fontFamily: "monospace" }}>{a.source_ip || "-"}</span>
                  {isBlocked && (
                    <span style={{ marginLeft: "0.4rem", padding: "0.15rem 0.4rem", background: "#ff4d4f", color: "#fff", borderRadius: "3px", fontSize: "0.75rem", fontWeight: "bold" }}>
                      BLOCKED
                    </span>
                  )}
                </td>
                <td style={{ padding: "0.6rem", fontFamily: "monospace" }}>{a.dest_ip || "-"}</td>
                <td style={{ padding: "0.6rem" }}>{(a.type || "-").replace("_", " ").toUpperCase()}</td>
                <td style={{ padding: "0.6rem", color: severityColors[a.severity] || severityColors[(a.severity || "").charAt(0).toUpperCase() + (a.severity || "").slice(1).toLowerCase()] || "#333", fontWeight: "bold" }}>
                  {a.severity || "Unknown"}
                </td>
                <td style={{ padding: "0.6rem" }}>{a.detail || "-"}</td>
                <td style={{ padding: "0.6rem", textAlign: "center" }}>
                  {isBlocked ? (
                    <button
                      onClick={() => onUnblockIP(a.source_ip)}
                      style={{
                        padding: "0.25rem 0.6rem",
                        background: "#52c41a",
                        color: "#fff",
                        border: "none",
                        borderRadius: "4px",
                        fontSize: "0.78rem",
                        cursor: "pointer",
                      }}
                    >
                      Unblock
                    </button>
                  ) : (
                    <button
                      onClick={() => onBlockIP(a.source_ip)}
                      style={{
                        padding: "0.25rem 0.6rem",
                        background: (a.severity || "").toLowerCase() === "high" ? "#ff4d4f" : "#495057",
                        color: "#fff",
                        border: "none",
                        borderRadius: "4px",
                        fontSize: "0.78rem",
                        cursor: "pointer",
                      }}
                    >
                      Block IP
                    </button>
                  )}
                </td>
              </tr>
            );
          })
        )}
      </tbody>
    </table>
  );
}
